+/// limit refuses.
+///
+/// # Errors
+/// An unstated or exceeded maximum taper, or unstated guide planes on a
+/// U/V machine, named.
+pub fn taper_door(machine: &Machine, taper_deg: f64) -> Result<(), String> {
+    if taper_deg == 0.0 {
+        return Ok(());
+    }
