+    }
+    for script in [
+        "capabilities = 1;",
+        "wireEdm = false;",
+        "wireEdm = 1;",
+        "wireEdm = \"true\";",
+    ] {
+        assert!(
+            !serves(script, Kind::WireEdm).expect("manifest loads"),
+            "{script}"
+        );
+    }
+}
