+fn post_options_refuses_enum_types_without_applying_valid_fields() {
+    let mut c = Client::new();
+    c.ok("add_setup", json!({ "name": "Setup1" }));
+    c.ok("set_post_options", json!({ "setup": "Setup1", "per_op": true }));
