+    let (path, _) = generate(&world, &op, "FaceFront").expect("aligned face pick generates");
+    let feed_pts: Vec<_> = path.moves.iter().filter(|m| m.feed.is_some()).collect();
+    assert!(!feed_pts.is_empty());
