+
+/// Distance from (x, y) to the axis box [x0, x1] x [y0, y1].
+fn to_box(x: f64, y: f64, b: [f64; 4]) -> f64 {
+    let dx = (b[0] - x).max(x - b[1]).max(0.0);
+    let dy = (b[2] - y).max(y - b[3]).max(0.0);
+    dx.hypot(dy)
+}
