+fn nc_path(tag: &str) -> std::path::PathBuf {
+    let p = std::env::temp_dir().join(format!("camcraft-slot-ext-{tag}-{}.nc", std::process::id()));
+    let _ = std::fs::remove_file(&p);
+    p
+}
