+    let id = f
+        .faces
+        .iter()
+        .filter(|fa| fa.normal[2].abs() > 0.99)
+        .filter(|fa| fa.loops.iter().flat_map(|l| &l.verts).any(|&v| (f.verts[v as usize][2] - H).abs() < 1e-9))
