+            *used_center = used_center.union(&Region::sweep(std::slice::from_ref(&chain), lay.b)?)?;
+            *cleared = cleared.union(&Region::sweep(std::slice::from_ref(&chain), r + lay.b)?)?;
+            layouts.push(lay);
+            placed = true;
+        }
+    }
+    Ok(placed)
