+fn tangent(m: &Move, start: bool) -> (f64, f64) {
+    let v = match m.arc {
+        None => (m.to.x - m.from.x, m.to.y - m.from.y),
+        Some(arc) => {
+            let p = if start { m.from } else { m.to };
+            let (dx, dy) = (p.x - arc.center.x, p.y - arc.center.y);
+            if arc.ccw { (-dy, dx) } else { (dy, -dx) }
+        }
+    };
+    let l = v.0.hypot(v.1);
+    (v.0 / l, v.1 / l)
