+            let dot = u.0 * w.0 + u.1 * w.1;
+            assert!(dot > 0.0 && cross.abs() <= budget, "{what}: kink {cross} at an arc turn end (move {i}: {before:?} / {m:?} / {after:?})");
+        }
+        radii.push(rho);
+    }
+    radii
