+
+/// The `t` (all reals) where `lo <= k - t*m <= hi`; `None` when never.
+fn band(k: f64, m: f64, lo: f64, hi: f64) -> Option<(f64, f64)> {
+    if m.abs() <= f64::EPSILON {
