+    press(&mut h, "Remove skim 2");
+    assert_eq!(draft(&h).skims.len(), 1);
+    assert!(live(&h).skims.is_empty(), "edits wait for Apply");
+    press(&mut h, "Apply");
+    h.state_mut().drain_actions();
+    assert_eq!(live(&h).skims, draft(&h).skims);
