+        Step::new("kernel", &["test", "-p", "camcraft-kernel"], ""),
+        Step::new("clippy", &["clippy"], ""),
+        Step::new("release build", &["test", "--release", "--no-run"], ""),
+        Step::new("ui cwd", &["test"], "ui"),
+    ];
+    let waves = lanes::waves(&steps);
